//! `proposals/talend-<project>.md`: the translation for a reviewer (EKOS RFC 0268 §Files).

use crate::{Layer, Report};
use std::fmt::Write;

/// The report as Markdown: counts first, then the questions, the models, the statements and the
/// watermarks.
pub fn markdown(r: &Report) -> String {
    let mut out = String::new();
    let enabled = r.models.iter().filter(|m| m.enabled).count();
    let _ = writeln!(
        out,
        "# Talend project `{}` → dbt (EKOS RFC 0268)\n",
        r.project
    );
    let _ = writeln!(
        out,
        "Generated by ekos-lakehouse. {} jobs, {} models ({} enabled), {} questions, {} statements, {} watermarks. Nothing here has run against data: every model is **not verified by execution** until the differential run (RFC 0268 phase 3).\n",
        r.jobs.len(),
        r.models.len(),
        enabled,
        r.questions.len(),
        r.statements.len(),
        r.watermarks.len()
    );
    let _ = writeln!(out, "## Models by layer and rule\n");
    let _ = writeln!(
        out,
        "| Layer | Rule | Written | Enabled |\n|---|---|---|---|"
    );
    for ((layer, rule), (n, e)) in r.counts() {
        let _ = writeln!(out, "| {layer:?} | {rule:?} | {n} | {e} |");
    }
    if !r.questions.is_empty() {
        let _ = writeln!(out, "\n## Questions\n");
        for q in &r.questions {
            let _ = writeln!(
                out,
                "- **{}** `{}.{}`: {}",
                q.kind, q.job, q.component, q.question
            );
        }
    }
    for layer in [Layer::Gold, Layer::Silver] {
        let _ = writeln!(out, "\n## {layer:?} models\n");
        let _ = writeln!(
            out,
            "| Model | Job | Rule | Materialization | Fidelity | Enabled | Why not |\n|---|---|---|---|---|---|---|"
        );
        for m in r.models.iter().filter(|m| m.layer == layer) {
            let why = m.gaps.join("; ").replace('|', "\\|").replace('\n', " ");
            let _ = writeln!(
                out,
                "| `{}` | {} | {:?} | {} | {:?} | {} | {} |",
                m.name,
                m.job,
                m.rule,
                m.materialization,
                m.fidelity,
                if m.enabled { "yes" } else { "no" },
                why
            );
        }
    }
    if !r.statements.is_empty() {
        let _ = writeln!(out, "\n## Statements (run from a trigger; no model)\n");
        for s in &r.statements {
            let _ = writeln!(
                out,
                "- `{}.{}`: {} {}{}",
                s.job,
                s.component,
                s.verb,
                s.table.as_deref().unwrap_or("?"),
                if s.bookkeeping {
                    " (run bookkeeping)"
                } else {
                    ""
                }
            );
        }
    }
    if !r.watermarks.is_empty() {
        let _ = writeln!(out, "\n## Watermarks\n");
        for w in &r.watermarks {
            let _ = writeln!(
                out,
                "- `{}`: `context.{}` set by {} from `{}`, read by {}",
                w.job,
                w.var,
                w.set_by,
                w.column,
                if w.read_by.is_empty() {
                    "nothing".to_string()
                } else {
                    w.read_by.join(", ")
                }
            );
        }
    }
    out
}
